(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.3)*18 + Math.cos(y*0.013-t*0.22)*12 + Math.sin((x+y)*0.008+t*0.15)*8;
  const w1y = Math.cos(y*0.02-t*0.27)*18 + Math.sin(x*0.016+t*0.33)*12 + Math.cos((x-y)*0.009-t*0.18)*8;
  const sx = x+w1x, sy = y+w1y;
  const w2x = Math.sin(sx*0.025-t*0.4)*6 + Math.cos(sy*0.02+t*0.35)*4;
  const w2y = Math.cos(sy*0.022+t*0.38)*6 + Math.sin(sx*0.018-t*0.32)*4;
  const fx = sx+w2x, fy = sy+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.07, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.09, 1.7, 0.85],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.055, 2.3, 1.1],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.11, 1.5, 0.9],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.065, 2.6, 1.05],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.08, 1.9, 0.95],
    [80+Math.sin(t*0.45+3)*110, 120+Math.cos(t*0.65+2)*70, 0.075, 2.1, 0.88],
    [400+Math.cos(t*0.55+1)*70, 190+Math.sin(t*0.75+4)*50, 0.06, 2.4, 1.12]
  ];
  let aS=0, iS=0, cS=0;
  for(const[sX,sY,f,sp,w]of src){
    const d=Math.sqrt((fx-sX)**2+(fy-sY)**2);
    aS+=Math.sin(d*f-t*sp)*w;
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5)*w;
    cS+=Math.sin(d*f*1.3-t*sp*0.8+3.0)*w*0.5;
  }
  const n=8;const act=aS/n,inh=iS/n,coupling=cS/n;
  const bg=(Math.sin(fx*0.035+fy*0.022+t*0.9)+Math.sin(fx*0.028-fy*0.038+t*1.2)+Math.sin(fx*0.05+fy*0.05+t*0.6))/3;
  const caustic=Math.sin(fx*0.08+t*1.8)*Math.sin(fy*0.09-t*1.5)+Math.sin((fx+fy)*0.06-t*2.2)*Math.sin((fx-fy)*0.07+t*1.9);
  const dist=Math.sqrt((fx-cx)**2+(fy-cy)**2),ang=Math.atan2(fy-cy,fx-cx);
  const spiral=(Math.sin(dist*0.045-ang*4-t*1.6)+Math.sin(dist*0.035+ang*5-t*1.3)+Math.sin(dist*0.06-ang*2+t*0.9))*0.333;
  const ridge=Math.abs(Math.sin(fx*0.12+fy*0.08+t*1.4)*Math.cos(fx*0.1-fy*0.11-t*1.1));
  const reaction=Math.tanh((act-inh*0.65+coupling*0.4+bg*0.25+spiral*0.35+caustic*0.15+ridge*0.1)*2.0);
  const cell=Math.tanh((Math.sin(fx*0.14)*Math.sin(fy*0.14)+Math.sin((fx+fy)*0.09+t)*0.4+Math.sin(fx*0.07-fy*0.08-t*0.7)*0.3)*1.6)*0.25;
  const micro=Math.sin(fx*0.3+fy*0.25+t*3)*Math.sin(fx*0.28-fy*0.32-t*2.7)*0.08;
  const blend=reaction*0.65+cell*0.2+micro;
  const v=blend*0.5+0.5;
  const breath=0.92+Math.sin(t*0.4)*0.08;
  const lum=(0.78+Math.sin(reaction*Math.PI)*0.22)*breath;
  const edge=Math.abs(reaction)>0.72?1.18:Math.abs(reaction)>0.5?1.08:1.0;
  const glow=Math.max(0,1-dist/280)*0.12;
  const pal=[
    [5,12,52],[12,45,95],[18,85,120],[25,135,135],[55,175,130],
    [160,195,80],[220,185,60],[230,140,55],[215,90,60],[175,50,65],
    [120,25,55],[60,15,48],[5,12,52]
  ];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const boost=1+glow;
  return[
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge*boost+glow*30)|0),
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge*boost+glow*50)|0),
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge*boost+glow*70)|0)
  ];
}
